var VISKEYS=Object.keys(VIS_EMOJI).concat(Object.keys(VIS_SVGKEYS)).sort(function(a,b){return b.length-a.length});
function visualFor(en){
 var raw=String(en||"").trim();if(!raw)return null;
 if(/^[a-zA-Z]$/.test(raw))return{t:"tile",v:raw.toUpperCase()};
 var e=" "+raw.toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ")+" ";
 var words=e.trim().split(" ");
 if(words.length===1&&NUMWORDS[words[0]]!==undefined)return{t:"tile",v:NUMWORDS[words[0]]};
 if(words.length===1&&(words[0]==="tall"||words[0]==="short"||words[0]==="big"||words[0]==="small"))return{t:"svg",v:"measure"};
 for(var i=0;i<VISKEYS.length;i++){var k=VISKEYS[i];if(e.indexOf(" "+k+" ")>=0||e.indexOf(" "+k+"s ")>=0){if(VIS_SVGKEYS[k])return{t:"svg",v:VIS_SVGKEYS[k]};return{t:"emoji",v:VIS_EMOJI[k]}}}
 return null;
}
function visHTML(en,sm){var v=visualFor(en);if(!v)return "";if(v.t==="emoji")return '<span class="visEm'+(sm?" sm":"")+'" aria-hidden="true">'+v.v+'</span>';if(v.t==="tile")return '<span class="visTile" aria-hidden="true">'+esc(v.v)+'</span>';return '<span class="visSvg'+(sm?" sm":"")+'" aria-hidden="true">'+VIS_SVG[v.v]+'</span>'}
