var DB=null;var MEM={};
function idbOpen(){return new Promise(function(res){try{var r=indexedDB.open("zamzam-academy",1);r.onupgradeneeded=function(){r.result.createObjectStore("kv")};r.onsuccess=function(){DB=r.result;res()};r.onerror=function(){res()}}catch(e){res()}})}
function idbSet(k,v){return new Promise(function(res){if(!DB){MEM[k]=v;res();return}try{var tx=DB.transaction("kv","readwrite");tx.objectStore("kv").put(v,k);tx.oncomplete=function(){res()};tx.onerror=function(){MEM[k]=v;res()}}catch(e){MEM[k]=v;res()}})}
function idbGet(k){return new Promise(function(res){if(!DB){res(MEM[k]);return}try{var tx=DB.transaction("kv","readonly");var rq=tx.objectStore("kv").get(k);rq.onsuccess=function(){res(rq.result)};rq.onerror=function(){res(MEM[k])}}catch(e){res(MEM[k])}})}
