function mistakeAdd(st,item){if(!Array.isArray(st.mistakes))st.mistakes=[];var ex=null;for(var i=0;i<st.mistakes.length;i++){if(st.mistakes[i].key===item.key)ex=st.mistakes[i]}if(!ex){ex={key:item.key,q:item.q,qSo:item.qSo||"",opts:item.opts||null,ans:item.ans,accept:item.accept||null,why:item.why||"",type:item.type||"mcq",lesson:item.lesson||0,wordEn:item.wordEn||"",days:[]};st.mistakes.push(ex)}if(item.wordEn){var card=null;for(var j=0;j<st.srs.length;j++){if(st.srs[j].en===item.wordEn)card=st.srs[j]}if(card){card.box=0;card.due=Date.now()+86400000}else{st.srs.push({en:item.wordEn,so:item.wordSo||"",box:0,due:Date.now()+86400000})}}return ex}
