function listenBtnsHTML(text,slowLabel){
 var wc=String(text||"").trim().split(/\s+/).filter(Boolean).length;
 return '<div class="u-row u-wrap u-mt-3 u-mb-3"><button class="u-grow u-t-lg u-minw btn" data-speak="'+esc(text)+'">'+uiIcon("wave")+' '+lng('Dhegeyso','Listen')+'</button><button class="u-grow u-minw btn secondary" data-speak="'+esc(text)+'" data-slow="1">'+uiIcon("slow")+' '+lng('Tartiiib dhegeyso','Listen slowly')+'</button></div><p class="small muted">'+lng('Jumlada/eryagu waa <strong>'+wc+' eray</strong>. Inta jeer ee aad rabto waad dhegeysan kartaa — halkan taabo ','The sentence has '+wc+' word'+(wc===1?"":"s")+'. Tap ')+uiIcon("wave")+lng(' marka hore, kadib qor.',' Listen first — you can listen as many times as you need — then type what you hear.')+'</p>';
}
