 try{var r=new SR();r.lang="en-GB";r.interimResults=false;r.onresult=function(e){var said=e.results[0][0].transcript;var tw=norm(target).split(" ");var sw=norm(said).split(" ");var hit=tw.filter(function(w){return sw.indexOf(w)>=0}).length;if(!Array.isArray(S.skillLog))S.skillLog=[];S.skillLog.push({skill:"speaking",ok:hit===tw.length?1:0,date:todayStr()});if(!guestMode){var spk="sp|"+norm(target);if(hit===tw.length){recDay(S,spk,todayStr());recDay(S,"sk:speaking|"+spk,todayStr());mistakeCorrect(S,spk,todayStr())}else{mistakeAdd(S,{key:spk,q:"Say it in English: "+target,qSo:"Ingiriisi ku dheh: "+target,ans:target,why:target,type:"speaking",lesson:cur?cur.n:0,wordEn:"",wordSo:""})}}save();out.innerHTML="Waxaad tidhi: <strong>"+esc(said)+"</strong><br>Erayada isku mid ah: <strong>"+hit+" / "+tw.length+"</strong>. "+(hit===tw.length?"Dhammaan erayadii waa sax!":"Isku day mar kale, eray kasta si cad u dheh.")+"<br><span class='small'>Tani waa isbarbardhig erayo — ma aha qiimeyn dhawaaq oo cilmi ah.</span>"};r.onerror=function(){out.textContent="Mikrofoonku ma shaqeyn. Dhegeyso oo ku celceli cod dheer."};r.start();out.textContent="🎙️ Dhegeysanayaa... hadda dheh jumladda."}catch(e){out.textContent="Mikrofoonku ma shaqeyn."}
