var VERBSET={is:1,am:1,are:1,was:1,were:1,drink:1,drinks:1,eat:1,eats:1,read:1,reads:1,cook:1,cooks:1,go:1,goes:1,work:1,works:1,learn:1,learns:1,open:1,opens:1,clean:1,cleans:1,sleep:1,sleeps:1,wake:1,wakes:1,has:1,have:1,like:1,likes:1,play:1,plays:1,watch:1,watches:1,live:1,lives:1,help:1,helps:1,buy:1,buys:1,take:1,takes:1,walk:1,walks:1,sit:1,sits:1,stand:1,stands:1,write:1,writes:1,say:1,says:1,see:1,sees:1,make:1,makes:1,want:1,wants:1,need:1,needs:1,love:1,loves:1,celebrate:1,celebrates:1,get:1,gets:1,use:1,uses:1};
