function wordOrderHTML(){var h='<h3>'+uiIcon("repeat")+' '+lng('Habka erayada: Soomaali iyo Ingiriisi','Word order: Somali and English')+'</h3><p class="small">Ingiriisiga ficilku <strong>dhexda</strong> buu ku jiraa: Qof ■ → Ficil ● → Shay ▲. Soomaaliga ficilku <strong>wuu dambeyaa</strong>: Shay ▲ → Qof ■ → Ficil ●. / In English the verb is in the middle: Person ■ → Action ● → Object ▲. In Somali the verb comes last.</p>';WO_PAIRS.forEach(function(p){function row(words,roles){return words.map(function(w,i){var r=roles[i];return '<span class="u-gap-1 tile '+r+'">'+ROLE_META[r][0]+' '+esc(w)+'<small>'+lng(ROLE_META[r][2],ROLE_META[r][1])+'</small></span>'}).join(" → ")}h+='<div class="u-mt-3 u-mb-3"><p class="u-mt-1 u-mb-1"><strong>EN:</strong> '+row(p.en,["subj","verb","obj"])+' '+speakBtn(p.enT)+'<br><span class="small muted">'+esc(p.enT)+'</span></p><p class="u-mt-1 u-mb-1"><strong>SO:</strong> '+row(p.so,["obj","subj","verb"])+'<br><span class="small muted">'+esc(p.soT)+'</span></p></div>'});return h}
