var PROPS=[["in","in","ku jira"],["on","on","dusha"],["under","under","hoosta"],["behind","behind","gadaasha"],["next to","next to","garabka / ku xiga"]];
function propHTML(){return '<h3>'+lng('⚽ Horgaleeyeyaasha: kubbad iyo sanduuq','Prepositions: ball and box')+'</h3><div class="u-ta-center" id="propStage">'+propSVG(propSel)+'</div><p class="u-ta-center u-t-lg"><strong>The ball is '+esc(propSel)+' the box.</strong><br><span class="muted">Kubbaddu waxay '+esc((PROPS.filter(function(x){return x[0]===propSel})[0]||[])[2]||"")+' sanduuqa.</span></p><div class="u-row u-wrap u-j-center">'+PROPS.map(function(p){return '<button class="chipbtn '+(propSel===p[0]?"sel":"")+'" data-prop="'+p[0]+'">'+esc(p[1])+' / '+esc(p[2])+'</button>'}).join("")+'</div>'}
function wireProps(root){root.querySelectorAll("[data-prop]").forEach(function(b){b.addEventListener("click",function(){propSel=b.dataset.prop;var st=document.getElementById("propStage");if(st)st.innerHTML=propSVG(propSel);var wrap=document.getElementById("propWrap");if(wrap){wrap.innerHTML=propHTML();bindSpeak(wrap);wireProps(wrap)}speak("The ball is "+propSel+" the box")})})}
function animHTML(){function card(id,title,so,inner){return '<div class="animbox"><h4 class="u-mt-1 u-mb-1">'+title+'<br><span class="small muted">'+so+'</span></h4><div class="animstage" id="'+id+'">'+inner+'</div><button class="btn secondary" data-anim="'+id+'">'+uiIcon("play")+' '+lng('Mar kale ciyaar','Replay')+'</button> <button class="btn ghost" data-pause="'+id+'">'+uiIcon("pause")+' '+lng('Jooji','Pause')+'</button></div>'}var push='<div class="u-row u-a-center"><div class="animBox pushA"></div><span class="u-t-xl">'+uiIcon("arrow")+uiIcon("back")+'</span></div>';var door='<svg viewBox="0 0 60 80" class="u-h-80"><rect x="8" y="6" width="44" height="68" fill="none" stroke="#7c4a21" stroke-width="3"/><g class="doorA"><rect x="10" y="8" width="40" height="64" fill="#d99a63"/><circle cx="44" cy="40" r="3" fill="#7c4a21"/></g></svg>';var speed='<div class="u-stack"><div class="animBall fastA"></div><div class="animBall slowA is-alt"></div></div>';var lift='<div class="animBox liftA"></div>';return '<h3>'+uiIcon("video")+' '+lng('Dhaqdhaqaaqyo yaryar','Micro-animations')+'</h3><p class="small muted">Dhaqdhaqaaqu waa gaaban yahay, waa la ciyaari karaa mar kale, waana la joojin karaa. Haddii aaladdaadu “reduced motion” shidan tahay, dhaqdhaqaaqu wuu istaagaa. / Animations are brief, replayable and pausable, and stop when your device prefers reduced motion.</p><div class="grid grid2">'+card("anPush","Push and pull","Riix oo jiid",push)+card("anDoor","Open and close","Fur oo xir",door)+card("anSpeed","Fast and slow","Degdeg iyo tartiib",speed)+card("anLift","Lift and carry","Kor u qaad oo qaad",lift)+'</div>'}
function wireAnims(root){root.querySelectorAll("[data-anim]").forEach(function(b){b.addEventListener("click",function(){var st=document.getElementById(b.dataset.anim);if(!st)return;st.classList.remove("play");void st.offsetWidth;st.classList.add("play")})});root.querySelectorAll("[data-pause]").forEach(function(b){b.addEventListener("click",function(){var st=document.getElementById(b.dataset.pause);if(st)st.classList.toggle("play")})});root.querySelectorAll(".animstage").forEach(function(s){s.classList.add("play")})}
